const colors=['var(--muted)','var(--viz-series-1)','var(--viz-series-2)','var(--viz-series-3)'];
const names=['Win / tie','Loss <10k','Loss 10–20k','Loss ≥20k'];
const freq=root.querySelector('#loss-frequency');
const heading=document.createElement('h3');heading.textContent='Loss severity · share of all games';freq.append(heading);
const legend=document.createElement('div');legend.className='legend text-small';
names.forEach((name,i)=>{const item=document.createElement('span');const s=document.createElement('span');s.className='swatch';s.style.background=colors[i];item.append(s,document.createTextNode(name));legend.append(item)});freq.append(legend);
data.cohorts.forEach(c=>{
 const counts=[0,0,0,0];c.rows.forEach(r=>counts[r.margin>=0?0:r.margin>-10000?1:r.margin>-20000?2:3]++);
 const row=document.createElement('div');row.className='freq-row';const lab=document.createElement('div');lab.className='freq-label';
 const name=document.createElement('span');name.textContent=c.label;const value=document.createElement('span');value.className='tabular-nums text-small';value.textContent=`${c.summary.losses}/${c.summary.n} losses · worst ${(c.summary.worst/1000).toFixed(1)}k`;lab.append(name,value);row.append(lab);
 const track=document.createElement('div');track.className='freq-track';track.setAttribute('role','img');track.setAttribute('aria-label',c.label+': '+names.map((n,i)=>`${n}: ${counts[i]}`).join(', '));
 counts.forEach((n,i)=>{if(!n)return;const seg=document.createElement('div');seg.className='freq-segment';seg.style.width=(100*n/c.summary.n)+'%';seg.style.background=colors[i];seg.setAttribute('data-tooltip',`${c.label} · ${names[i]}: ${n} games (${(100*n/c.summary.n).toFixed(1)}%)`);track.append(seg)});row.append(track);
 const detail=document.createElement('div');detail.className='text-small';detail.textContent=`Loss counts: ${counts[1]} under 10k · ${counts[2]} at 10–20k · ${counts[3]} at least 20k`;row.append(detail);freq.append(row);
});
const container=root.querySelector('#loss-ledger');
function draw(){
const width=container.clientWidth;if(!width)return;const left=104,right=48,top=40,bottom=50,h=400;
const x=d3.scaleLinear().domain(d3.extent([0,...data.decomposition.map(d=>d.value)])).nice().range([left+8,width-right-8]);
const y=d3.scaleBand().domain(data.decomposition.map(d=>d.label)).range([top,h-bottom]).padding(.28);
container.replaceChildren();const svg=d3.select(container).append('svg').attr('class','audit-svg').attr('viewBox',`0 0 ${width} ${h}`).attr('role','img').attr('aria-label','Revenue and spending differences versus V50 sum exactly to minus 15,071 coins. Wool deficit is 36,587 coins.');
svg.append('rect').attr('data-chart-frame','').attr('x',left).attr('y',top-10).attr('width',width-left-right).attr('height',h-top-bottom+20).attr('fill','none').attr('stroke','var(--border)');
svg.append('g').attr('transform',`translate(0,${h-bottom+10})`).call(d3.axisBottom(x).ticks(width<500?3:5).tickFormat(v=>v/1000+'k'));
svg.append('line').attr('x1',x(0)).attr('x2',x(0)).attr('y1',top-10).attr('y2',h-bottom+10).attr('stroke','var(--border)');
svg.append('text').attr('class','axis-title').attr('data-axis','x').attr('x',(left+width-right)/2).attr('y',h-5).attr('text-anchor','middle').text('Contribution to margin (coins)');
svg.append('text').attr('class','axis-title').attr('data-axis','y').attr('x',0).attr('y',18).text('Ledger item');
data.decomposition.forEach(d=>{
 const cy=y(d.label),val=d.value;
 svg.append('text').attr('x',left-6).attr('y',cy+y.bandwidth()/2+4).attr('text-anchor','end').text(d.label);
 svg.append('rect').attr('x',Math.min(x(0),x(val))).attr('y',cy).attr('width',Math.abs(x(val)-x(0))).attr('height',y.bandwidth()).attr('fill',val<0?'var(--viz-series-2)':'var(--viz-series-1)');
 svg.append('rect').attr('data-chart-hit','').attr('x',left).attr('y',cy-3).attr('width',width-left-right).attr('height',Math.max(32,y.bandwidth())).attr('fill','transparent').attr('data-tooltip',`${d.label}: ${val>0?'+':''}${val.toLocaleString()} coins`);
 if(width>=500||Math.abs(val)>9000)svg.append('text').attr('x',val<0?x(val)+4:x(val)+4).attr('y',cy+y.bandwidth()/2+4).text((val>0?'+':'')+(val/1000).toFixed(1)+'k');
});
}
new ResizeObserver(draw).observe(container);draw();
